def word_frequency(text: str) -> dict[str, int]:
    import re
    frequency = {}
    for word in text.split():
        cleaned = re.sub(r'^[^a-z]+|[^a-z]+$', '', word.lower())
        if cleaned:
            frequency[cleaned] = frequency.get(cleaned, 0) + 1
    return frequency
